contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that tests scheduling behavior relative to getMinDelay().
    // Inputs: target addr, value, arbitrary data, predecessor, salt, and requested delay.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // We will attempt to call c.schedule(...) from this contract which must have PROPOSER_ROLE
        // The freshly deployed c gives the deployer (which is the checker) the TIMELOCK_ADMIN_ROLE and possibly proposers/executors arrays were provided at construction.
        // However our test cannot assume this contract has PROPOSER_ROLE; so we use the public view to read minDelay first.
        uint256 min = c.getMinDelay();

        // Try scheduling and record whether it reverted
        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe whether operation is recorded as scheduled
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        bool isOp = c.isOperation(id);

        // General rule (single assert): if we attempted to schedule with delay < min then the call must have reverted and operation must not be present;
        // if we attempted with delay >= min then the call (if not reverted) implies operation is present. We express this as:
        // (delay < min) => (reverted && !isOp)
        // (delay >= min) => (!reverted => isOp)
        // Combined into one boolean formula for the assert.
        assert(
            (delay < min ? (reverted && !isOp) : true) &&
            (delay >= min ? (!reverted ? isOp : true) : true)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry: attempt to execute a single operation and assert postconditions.
    // We require that caller has EXECUTOR_ROLE or role is open; to keep things simple we only test cases
    // where execution does not send ETH and where predecessor is zero (no dependency).
    function run(address target, bytes calldata data, bytes32 salt) public payable {
        require(msg.value == 0, "no ether");

        // Prepare an id that the caller will try to execute. Use value = 0 and predecessor = 0.
        uint256 value = 0;
        bytes32 predecessor = bytes32(0);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Check whether the operation was ready before attempting execute.
        bool wasReady = c.isOperationReady(id);

        // Attempt execute and record whether it reverted.
        bool reverted;
        try c.execute(target, value, data, predecessor, salt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the attempt, observe whether operation is marked done.
        bool isDone = c.isOperationDone(id);

        // General rule: if execute succeeded (did not revert) then the operation must have been ready beforehand and is now done.
        assert((!reverted) ? (wasReady && isDone) : true);
    }

    receive() external payable {}
}

