    // Single-call test: if execute succeeds, the operation was ready before and is done after.
    function run(address target, bytes calldata data, bytes32 salt) public payable {
        // restrict to zero value to avoid dealing with ETH transfers
        uint256 value = 0;
        bytes32 predecessor = bytes32(0);

        // compute operation id using public getter
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // observe readiness before
        bool wasReady = c.isOperationReady(id);

        // attempt the execute call and record whether it reverted
        bool reverted;
        try c.execute(target, value, data, predecessor, salt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe done after
        bool isDone = c.isOperationDone(id);

